def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Given a string containing multiple groups of nested parentheses, separate them into separate strings and return the list of these.
    Each group is balanced (each open brace is properly closed) and not nested within each other. Ignore any spaces in the input string.
    """
    groups = []
    current_group = ''
    stack = []

    for char in paren_string:
        if char.isalpha():
            continue
        if char == '(':
            stack.append(char)
        elif char == ')':
            stack = []
            groups.append(current_group)
            current_group = ''
        elif char.isblank():
            continue
        else:
            current_group += char

    if stack:
        groups.append(current_group + stack.pop())

    while stack:
        groups.append(stack.pop())

    return groups

