def count_passing_ways(n, m):
    if n == 1 or m == 0:
        return 1
    if n == 2 and m == 1:
        return 1
    left = (m - 1) * (n - 1)
    right = (m - 1) * (n - 1)
    for i in range(2, m):
        left = (left + right) % (n * (n - 1))
        right = (left + right) % (n * (n - 1))
    return (left + right) % (n * (n - 1))

