def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D table to store the maximum happiness for each budget
    # and number of items
    dp = [[0] * (m+1) for _ in range(n+1)]

    # Fill in the table
    for i in range(1, n+1):
        for j in range(1, m+1):
            price, happiness = items[j-1]
            if i < price:
                # If the current budget is less than the item price,
                # the maximum happiness will be the same as the previous budget
                dp[i][j] = dp[i-1][j]
            else:
                # The maximum happiness will be the maximum of:
                # 1. The previous budget and the current number of items
                # 2. The current budget minus the item price and the previous number of items plus the item happiness
                dp[i][j] = max(dp[i-1][j], dp[i-price][j-1] + happiness)

    # The maximum happiness will be the maximum value in the last row
    # of the table
    return max(dp[n])

