def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.
    """
    # Initialize a dictionary to store the results of sub-problems
    # Key: (n, k) tuple, Value: number of ways to partition n into k parts
    memo = {(n, k): 0 for n in range(n+1) for k in range(k+1)}

    # Initialize the base cases
    for i in range(x, n+1):
        memo[(i, 1)] = 1

    # Tabulate the results of sub-problems
    for i in range(1, k+1):
        for j in range(x, n+1):
            for m in range(1, j+1):
                memo[(j, i)] += memo[(j-m, i-1)]

    # Return the number of ways to partition n into k parts
    return memo[(n, k)]

