    # Use memoization to store already computed arrangements
    memory = {}

    def recurse(i, j, arr):
        # Base case: no more pots to arrange
        if i == m:
            return 1

        # Base case: no more types of flowers left
        if i > n:
            return 0

        # Check if this subproblem has already been solved
